import React from 'react';
import classNames from 'classnames';
import { ClickableDiv } from '@getvim/atomic-ui';
import './index.less';

interface AppMenuIconProps {
  onClick?: () => void;
  selected?: boolean;
  disabled?: boolean;
  loading?: boolean;
  id?: string;
}

const AppMenuIcon: React.FC<AppMenuIconProps> = ({
  onClick,
  selected = false,
  disabled = false,
  loading = false,
  id,
  children,
}) => (
  <ClickableDiv
    className={classNames('app-menu-icon-wrap', id, { selected }, { disabled }, { loading })}
    onClick={onClick}
  >
    {children}
  </ClickableDiv>
);

export default AppMenuIcon;
